import { useId } from "react";
import "./FocusProgress.css";

export interface FocusProgressProps {
  label: string;
  elapsedMinutes: number;
  totalMinutes: number;
}

function toMinutes(value: number): number {
  return Number.isFinite(value) && value > 0 ? Math.round(value) : 0;
}

export function FocusProgress({ label, elapsedMinutes, totalMinutes }: FocusProgressProps) {
  const labelId = useId();
  const total = toMinutes(totalMinutes);
  const elapsed = Math.min(toMinutes(elapsedMinutes), total);
  const percent = total === 0 ? 0 : Math.round((elapsed / total) * 100);
  const done = total > 0 && elapsed >= total;
  const summary = `${elapsed} of ${total} minutes`;

  return (
    <div className="focus-progress" data-done={done ? "true" : undefined}>
      <div className="focus-progress-head">
        <span id={labelId} className="focus-progress-label">
          {label}
        </span>
        <span className="focus-progress-value">
          {elapsed} / {total} min
        </span>
      </div>
      <div
        role="progressbar"
        tabIndex={0}
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={total}
        aria-valuenow={elapsed}
        aria-valuetext={summary}
        className="focus-progress-track"
      >
        <div className="focus-progress-fill" style={{ width: `${percent}%` }} />
      </div>
    </div>
  );
}
```

