  font-size: clamp(0.95rem, 0.6rem + 0.8vw, 1.25rem);
  font-weight: 600;
  color: var(--ink);
}

.focus-progress-value {
  font-size: clamp(0.85rem, 0.55rem + 0.6vw, 1.05rem);
  font-variant-numeric: tabular-nums;
  color: var(--muted);
  white-space: nowrap;
}

.focus-progress-track {
  position: relative;
  height: clamp(0.6rem, 0.4rem + 0.4vw, 0.9rem);
  border-radius: 999px;
  background: var(--axon-ahead);
  overflow: hidden;
}

.focus-progress-fill {
  height: 100%;
  border-radius: 999px;
  background: var(--myelin);
  transition: width 400ms ease-out;
}

.focus-progress[data-done="true"] .focus-progress-value {
  color: var(--myelin);
}

:root[data-motion="reduce"] .focus-progress-fill {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .focus-progress-fill {
    transition: none;
  }
}
